===== src/amr_dispatcher_proto/proto/chassis.proto =====
// 底盘链路健康与跟踪误差。
//
// 迁移来源：
//   amr_dispatcher_interfaces/msg/ChassisLinkHealth.msg
//   amr_dispatcher_interfaces/msg/TrackingError.msg
//
// 为什么 ChassisLinkHealth 是第一个迁移对象：
//   它几乎全是 uint64 计数器（frames_*、commands_*）。protobuf 的 varint
//   编码对这类「单调递增、数值随时间变大但高位多为 0」的数据非常友好；
//   而 rosidl 固定 8 字节。这是本方案里少数真有字节数收益的消息。
syntax = "proto3";

package amr_dispatcher.proto;

import "common.proto";

// 对应 amr_dispatcher_interfaces/msg/ChassisLinkHealth。
message ChassisLinkHealth {
  Header header = 1;

  string backend_name = 2;

  // UNKNOWN / HEALTHY / DEGRADED / CRITICAL
  //
  // 用 enum 而非 string 是刻意的改进：原 .msg 里这是个 string，
  // 拼写错误要到运行时才发现；enum 在编译期就能拦住。
  // 但桥接时仍需保留字符串形式，所以额外提供 backend_name 之外的
  // 原始 tier 文本（见 tier_text）。
  enum Tier {
    TIER_UNKNOWN = 0;
    TIER_HEALTHY = 1;
    TIER_DEGRADED = 2;
    TIER_CRITICAL = 3;
  }
  Tier tier = 3;

  // 兼容字段：原 .msg 的 tier 是 string，若上游写了枚举外的值
  // （例如未来新增状态），放进这里而不是丢弃，避免信息损失。
  // proto3 默认空字符串不占字节。
  string tier_text = 4;

  // ---- T2：链路质量统计（接收侧）----
  uint64 frames_total = 5;
  uint64 frames_success = 6;
  uint64 frames_lost = 7;
  uint64 frames_crc_error = 8;
  double loss_rate = 9;
  double avg_latency_ms = 10;
  double max_latency_ms = 11;
  bool is_healthy = 12;

  // ---- T3：命令送达率（下行 0xF3 是否真的被 MCU 收到）----
  // 语义：最近 commands_sent 帧下行里，MCU 回显序号已确认送达的比例。
  // -1 = 不适用（文本协议，或 MCU 尚未回显过序号）。
  //
  // 注意：这里不能用 uint32/uint64 表达「-1」哨兵值，
  // proto3 的无符号类型没有负数表示。所以显式拆成
  //   command_delivery_rate_valid + command_delivery_rate
  // 两个字段，桥接时把 -1 翻译成 valid=false。
  bool command_delivery_rate_valid = 13;
  double command_delivery_rate = 14;
  uint64 commands_sent = 15;
  uint64 commands_delivered = 16;

  // 预留：原 .msg 的字段若未来删除，在此声明编号，防止复用。
  // reserved 5, 6;
}

// 对应 amr_dispatcher_interfaces/msg/TrackingError。
message TrackingError {
  Header header = 1;

  // pure_pursuit / stanley
  string controller_name = 2;

  double lateral_error_m = 3;
  double heading_error_rad = 4;
  double lookahead_distance_m = 5;
  double target_linear_x_mps = 6;
  double target_angular_z_radps = 7;
  double actual_linear_x_mps = 8;
  double actual_angular_z_radps = 9;
  int32 nearest_waypoint_index = 10;
  bool arrived = 11;
}

===== src/amr_dispatcher_proto/proto/common.proto =====
// amr_dispatcher 的 protobuf 公共定义。
//
// 设计约束（务必先读，否则容易走偏）：
//   1. 这些 .proto 只用于 **ROS 话题**，不用于 service / action。
//      service/action 的 typesupport 是 request/response/event 三元组，
//      不在本方案的覆盖范围内（详见 docs/protobuf_migration_plan.md）。
//   2. 字段编号一旦发布就不允许复用；删除字段必须用 reserved。
//      这是 protobuf 相对 rosidl 的核心优势，别浪费。
//   3. 与现有 .msg 的字段语义保持一一对应，便于双向桥接。
syntax = "proto3";

package amr_dispatcher.proto;

// 时间戳。对应 builtin_interfaces/Time。
// 用两个字段而不是 google.protobuf.Timestamp，是为了精确对齐 ROS 的
// (sec, nanosec) 结构，桥接时零转换。
message Time {
  int32 sec = 1;
  uint32 nanosec = 2;
}

// 对应 std_msgs/Header。
// frame_id 用 string 而非 bytes：它是人类可读的坐标系名，不需要压缩。
message Header {
  Time stamp = 1;
  string frame_id = 2;
}

===== src/amr_dispatcher_proto/proto/dispatcher.proto =====
// 调度器状态与车辆链路状态。
//
// 迁移来源：
//   amr_dispatcher_interfaces/msg/DispatcherState.msg
//   amr_dispatcher_interfaces/msg/VehicleLinkState.msg
//
// 这是本方案里**最值得迁移**的一条：DispatcherState 里有
//   VehicleLinkState[] vehicle_links
// 这种嵌套结构，rosidl 需要为每个嵌套类型单独生成、单独注册；
// protobuf 的 message 嵌套是原生的，且 repeated 字段可以增量解析。
syntax = "proto3";

package amr_dispatcher.proto;

import "common.proto";

// 对应 amr_dispatcher_interfaces/msg/VehicleLinkState。
message VehicleLinkState {
  string vehicle_id = 1;

  // 执行后端：local_sim | vda5050
  string backend = 2;

  bool online = 3;
  bool busy = 4;

  // 隔离态：人工强清后，不再参与自动分配，需显式恢复
  bool quarantined = 5;

  bool position_valid = 6;
  string current_station_id = 7;
  double battery_percent = 8;

  // 状态时延（距上次收到状态报文的时间）。
  // int64 而非 uint64：若上游时钟异常可能出现负值，保留符号更安全。
  int64 state_age_ms = 9;

  string last_error = 10;
}

// 对应 amr_dispatcher_interfaces/msg/DispatcherState。
message DispatcherState {
  Header header = 1;

  string current_comparator = 2;
  uint32 queue_size = 3;
  uint32 queue_capacity = 4;
  uint32 active_missions_count = 5;
  uint32 paused_missions_count = 6;
  bool deadlock_detected = 7;

  string active_mission_id = 8;

  // 对应 string[] active_mission_ids
  repeated string active_mission_ids = 9;

  // 对应 VehicleLinkState[] vehicle_links
  // 结构化，替代平行数组
  repeated VehicleLinkState vehicle_links = 10;

  // ---- 派发计数器（累积，供 /metrics 与运维趋势）----
  uint64 dispatch_total = 11;
  uint64 dispatch_rejected_total = 12;
  uint64 dispatch_deferred_total = 13;
  uint64 lock_contention_total = 14;
  uint64 event_total = 15;

  // ---- 运行时拓扑叠加层（相位 11）----
  // 叠加层本身不改变 map_hash —— 它是同一张地图上的"临时交通管制"。
  bool overlay_active = 16;
  uint32 overlay_revision = 17;
  uint32 blocked_edges = 18;
  uint32 one_way_edges = 19;
}

===== src/amr_dispatcher_proto/proto/safety.proto =====
// 安全状态、拓扑状态、任务事件。
//
// 迁移来源：
//   amr_dispatcher_interfaces/msg/SafetyState.msg
//   amr_dispatcher_interfaces/msg/TopologyState.msg
//   amr_dispatcher_interfaces/msg/MissionEvent.msg
syntax = "proto3";

package amr_dispatcher.proto;

import "common.proto";

// 对应 amr_dispatcher_interfaces/msg/SafetyState。
//
// 安全相关消息有个额外好处：proto3 的字段编号一旦发布就冻结，
// 且删除字段必须显式 reserved。这比 rosidl 只能"追加字段"更严格，
// 对安全语义是加分项。
message SafetyState {
  Header header = 1;

  // INFO / WARN / CRITICAL
  enum Severity {
    SEVERITY_UNKNOWN = 0;
    SEVERITY_INFO = 1;
    SEVERITY_WARN = 2;
    SEVERITY_CRITICAL = 3;
  }
  Severity severity = 2;

  // 兼容字段：原 .msg 的 severity 是 string。
  // 若上游写了枚举外的值，放进这里而非丢弃。
  string severity_text = 3;

  bool motion_allowed = 4;

  // 1.0 = normal, 0.3 = warn reduced, 0.0 = stopped
  double speed_scale = 5;

  string active_stop_source = 6;
  string reason = 7;

  // 对应 string[] active_sources
  repeated string active_sources = 8;
}

// 对应 amr_dispatcher_interfaces/msg/TopologyState。
message TopologyState {
  Time stamp = 1;

  // 这四组平行数组在 rosidl 里靠下标对齐，一旦某一组长度不一致就错位。
  // protobuf 保持相同结构以兼容桥接，但推荐后续改成
  // repeated EdgeState 的结构化形式（见文件末尾注释）。
  repeated string active_edges = 2;
  repeated string locked_edges = 3;
  repeated string edge_owners = 4;
  repeated string deadlocked_nodes = 5;

  bool deadlock_detected = 6;

  // 演进建议（暂不实施，避免破坏桥接）：
  //   message EdgeState {
  //     string edge_id = 1;
  //     bool active = 2;
  //     bool locked = 3;
  //     string owner = 4;
  //   }
  //   repeated EdgeState edges = 7;
}

// 对应 amr_dispatcher_interfaces/msg/MissionEvent。
message MissionEvent {
  Time stamp = 1;
  string mission_id = 2;
  string order_id = 3;

  // queued / active / paused / finished / canceled / deadlock
  // 保留 string：事件名是开放的，未来可能新增，不适合固化成 enum。
  string event = 4;

  string from_state = 5;
  string to_state = 6;
  string reason = 7;
}

