  namespace bridge = amr_dispatcher_proto_bridge;
  EXPECT_EQ(bridge::ProtoTopicName("/plan/amr_01"), "/plan/amr_01_proto");
  EXPECT_EQ(bridge::ProtoTopicName("/tracking/error/amr_01"), "/tracking/error/amr_01_proto");
}

