  void Nav2FeedbackCb(
      const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::SharedPtr& gh,
      const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb,
      const std::weak_ptr<GoalHandleNavSeq>& seq_goal);
