  bool waiting_arrival_{false};  // fallback：已发 /plan，等待 arrived
  bool nav2_pending_{false};     // Nav2：单点 goal 在途，等待 result
  int completed_waypoints_{0};
  int failed_waypoints_{0};
};

}  // namespace amr_dispatcher_ros
