builtin_interfaces::msg::Time MakeStamp()
{
  builtin_interfaces::msg::Time t;
  t.sec = 1234;
  t.nanosec = 5678u;
  return t;
}

std_msgs::msg::Header MakeHeader()
{
  std_msgs::msg::Header h;
  h.stamp = MakeStamp();
  h.frame_id = "map_frame";
  return h;
}

